          activities: [
            { slot: "12h–13h", name: "Arrivée Schiphol + transfert", type: "logistics", duration: 60, icon: "✈️", note: "Depuis l'aéroport de Schiphol, le train direct rejoint Amsterdam Centraal en 17 minutes pour environ 5€. C'est le moyen le plus rapide et le plus fiable : les taxis coûtent entre 40 et 55€ selon la circulation." },
            { slot: "13h30–15h", name: "Déjeuner + premier aperçu du canal Ring", type: "food", duration: 90, icon: "🍽️", note: "Repas rapide dans le Centrum, puis première promenade sur les quais du Herengracht (canal des Seigneurs). Les maisons à pignons du XVIIe siècle, légèrement penchées vers l'avant pour faciliter le chargement, sont inscrites à l'UNESCO depuis 2010. Budget repas entre 14 et 25€." },
            { slot: "15h–17h30", name: "Quartier Jordaan", type: "culture", duration: 150, icon: "🏘️", note: "Le Jordaan est l'ancien quartier des réfugiés protestants français (les Huguenots) et des artisans, aujourd'hui transformé en l'un des plus agréables d'Amsterdam. Les ruelles secondaires (Tichelstraat, Bloemstraat) concentrent les galeries indépendantes, les antiquaires et les cafés bruns. Pas de billet d'entrée, exploration libre." },
            { slot: "17h30–19h", name: "Canaux Keizersgracht et Prinsengracht", type: "culture", duration: 90, icon: "🚶", note: "Le Keizersgracht (canal de l'Empereur) et le Prinsengracht (canal du Prince) forment avec le Herengracht le cœur du canal Ring classé à l'UNESCO. La lumière de fin d'après-midi sur les façades et les ponts en pierre est particulièrement photographique." },
            { slot: "19h30–21h30", name: "Dîner dans un bruine kroeg", type: "food", duration: 120, icon: "🍺", note: "Les bruine kroegen (cafés bruns, ainsi nommés à cause de leurs murs et plafonds brunis par des décennies de fumée de pipe) sont les bistrots historiques d'Amsterdam. Ils servent de la bière locale (Heineken, Grolsch, Brouwerij 't IJ), du jenever (genièvre néerlandais) et une cuisine simple. Budget entre 18 et 30€." },
          ],
